function Buscar() {
  const navigate = useNavigate();
  const searchParams = useSearch({ from: "/buscar" });
  const { totalItems } = useCart();
  const [defaultAddress, setDefaultAddress] = useState<any>(null);
  const [categories, setCategories] = useState<any[]>([]);
  const [merchants, setMerchants] = useState<any[]>([]);
  const [merchantsHours, setMerchantsHours] = useState<any[]>([]);
  const [isLoading, setIsLoading] = useState(true);
  const [error, setError] = useState<string | null>(null);

  const [searchTerm, setSearchTerm] = useState(searchParams.q || "");
  const searchInputRef = useRef<HTMLInputElement>(null);

  const fetchData = async () => {
    setIsLoading(true);
    setError(null);
    try {
      const {
        data: { user },
      } = await supabase.auth.getUser();
      if (user) {
        const { data: addrData, error: addrError } = await supabase
          .from("customer_addresses" as any)
          .select("*")
          .eq("user_id", user.id)
          .eq("is_default", true)
          .maybeSingle();

        if (addrError) throw addrError;
        setDefaultAddress(addrData);

        const [cats] = await Promise.all([fetchMerchantCategories()]);
        setCategories(cats);

        if (addrData) {
          const mers = await fetchMerchants((addrData as any).city, (addrData as any).state);
          setMerchants(mers);
          if (mers.length > 0) {
            const hours = await fetchMerchantsHoursBatch(mers.map((m) => m.id));
            setMerchantsHours(hours);
          } else {
            setMerchantsHours([]);
          }
        } else {
          setMerchants([]);
          setMerchantsHours([]);
        }
      }
    } catch (err: any) {
      console.error("Error fetching data:", err);
      setError("Ocorreu um erro ao carregar o catálogo.");
    } finally {
      setIsLoading(false);
    }
  };

  useEffect(() => {
    fetchData();
    if (searchInputRef.current && !searchParams.categoria && !searchParams.q) {
      searchInputRef.current.focus();
    }
  }, []);

  useEffect(() => {
    setSearchTerm(searchParams.q || "");
  }, [searchParams.q]);

  const handleSearch = (e: React.FormEvent) => {
    e.preventDefault();
    navigate({
      to: "/buscar",
