import { createFileRoute, redirect, useNavigate, Outlet, useRouter } from "@tanstack/react-router";
import { useEffect, useState } from "react";
import { supabase } from "@/integrations/supabase/client";
import {
  ChevronLeft,
  ChevronRight,
  Star,
  MapPin,
  Plus,
  Trash2,
  Edit2,
  Home,
  Briefcase,
  Map as MapIcon,
  Loader2,
} from "lucide-react";
import { Button } from "@/components/ui/button";
import { toast } from "sonner";

export const Route = createFileRoute("/enderecos")({
  beforeLoad: async () => {
    const {
      data: { session },
    } = await supabase.auth.getSession();
    if (!session) {
      throw redirect({ to: "/login" });
    }
    return { session };
  },
  component: EnderecosLayout,
  head: () => ({
    meta: [{ title: "Meus Endereços | APOIS ENTREGA" }],
  }),
});

function EnderecosLayout() {
  const navigate = useNavigate();
  const [addresses, setAddresses] = useState<any[]>([]);
  const [isLoading, setIsLoading] = useState(true);

  const fetchAddresses = async () => {
    setIsLoading(true);
    const { data, error } = await supabase
      .from("customer_addresses" as any)
      .select("*")
      .order("is_default", { ascending: false })
      .order("created_at", { ascending: false });

    if (error) {
      console.error("Error fetching addresses:", error);
      toast.error("Erro ao carregar endereços");
    } else {
      setAddresses(data || []);
    }
    setIsLoading(false);
  };

  // TanStack Router hook para invalidar e recarregar dados quando a rota ganha foco
  const router = useRouter();

  useEffect(() => {
    // Busca inicial
    fetchAddresses();

    // Inscreve para atualizar sempre que houver navegação concluída para esta rota
    const unsub = router.subscribe("onResolved", (state) => {
      if (state.toLocation.pathname === "/enderecos") {
        fetchAddresses();
      }
    });

    // Também atualiza quando a janela ganha foco (ex: volta do navegador)
    window.addEventListener("focus", fetchAddresses);

    return () => {
      unsub();
      window.removeEventListener("focus", fetchAddresses);
    };
  }, [router]);

  const handleSetDefault = async (id: string) => {
    const {
      data: { user },
    } = await supabase.auth.getUser();
    if (!user) return;

    setIsLoading(true);
    // 1. Remove default from all other addresses of this user
    await (supabase as any)
      .from("customer_addresses")
      .update({ is_default: false })
      .eq("user_id", user.id);

    // 2. Set this one as default
    const { error } = await (supabase as any)
      .from("customer_addresses")
      .update({ is_default: true })
      .eq("id", id);

    if (error) {
      toast.error("Erro ao definir endereço padrão");
      setIsLoading(false);
      fetchAddresses();
    } else {
      toast.success("Endereço padrão atualizado");
      // 3. Navigate back to inicio immediately
      navigate({ to: "/inicio" });
    }
  };

  const handleDelete = async (id: string, isDefault: boolean) => {
    if (isDefault && addresses.length > 1) {
      toast.error("Defina outro endereço como padrão antes de excluir este");
      return;
    }

    if (!confirm("Tem certeza que deseja excluir este endereço?")) return;

    const { error } = await (supabase as any).from("customer_addresses").delete().eq("id", id);

    if (error) {
      toast.error("Erro ao excluir endereço");
    } else {
      toast.success("Endereço excluído");
      fetchAddresses();
    }
  };

  const getLabelIcon = (label: string) => {
    switch (label?.toLowerCase()) {
      case "casa":
        return Home;
      case "trabalho":
        return Briefcase;
      default:
        return MapIcon;
    }
  };

  return (
    <div className="flex min-h-full flex-col bg-black text-white overflow-x-hidden w-full">
      <header className="relative flex items-center justify-center px-4 py-4 sticky top-0 z-50 bg-black/85 backdrop-blur-lg">
        <button
          onClick={() => navigate({ to: "/inicio" })}
          className="absolute left-3 p-2 text-primary hover:bg-white/10 rounded-full transition-colors"
          aria-label="Voltar"
        >
          <ChevronLeft className="w-7 h-7" strokeWidth={2.5} />
        </button>
        <h1 className="text-xl font-extrabold tracking-tight">Meus Endereços</h1>
      </header>

      <main className="flex-1 px-5 pt-3 pb-28">
        <p className="text-zinc-400 text-[15px] mb-5">Selecione um endereço para suas entregas</p>

        {isLoading ? (
          <div className="flex flex-col items-center justify-center py-20">
            <Loader2 className="w-8 h-8 animate-spin text-primary" />
          </div>
        ) : addresses.length === 0 ? (
          <div className="flex flex-col items-center justify-center py-16 text-center space-y-3">
            <div className="w-20 h-20 bg-zinc-900 rounded-full flex items-center justify-center ring-1 ring-white/10">
              <MapPin className="w-10 h-10 text-zinc-700" />
            </div>
            <h2 className="text-lg font-bold">Nenhum endereço salvo</h2>
            <p className="text-zinc-500 text-sm px-8">
              Adicione um endereço para ver as opções de entrega na sua região.
            </p>
          </div>
        ) : (
          <div className="space-y-4">
            {addresses.map((addr) => {
              const Icon = getLabelIcon(addr.label);
              return (
                <div
                  key={addr.id}
                  onClick={() => !addr.is_default && handleSetDefault(addr.id)}
                  className={`relative rounded-3xl border p-4 pr-12 transition-all cursor-pointer ${
                    addr.is_default
                      ? "bg-zinc-950 border-primary/70 shadow-[0_0_20px_-8px_hsl(var(--primary)/0.5)]"
                      : "bg-zinc-950 border-zinc-800 hover:border-zinc-700"
                  }`}
                >
                  {/* Selection indicator */}
                  <span
                    className={`absolute top-4 right-4 w-6 h-6 rounded-full border-2 flex items-center justify-center ${
                      addr.is_default ? "border-primary" : "border-zinc-600"
                    }`}
                  >
                    {addr.is_default && <span className="w-3 h-3 rounded-full bg-primary block" />}
                  </span>

                  <div className="flex items-start gap-3">
                    <div className="shrink-0 w-12 h-12 rounded-full bg-primary/10 ring-1 ring-primary/40 flex items-center justify-center">
                      <Icon className="w-6 h-6 text-primary" />
                    </div>

                    <div className="min-w-0 flex-1">
                      <div className="flex items-center gap-2 flex-wrap">
                        <span className="font-extrabold text-white text-lg leading-none">
                          {addr.label}
                        </span>
                        {addr.is_default && (
                          <span className="inline-flex items-center gap-1 bg-primary text-black text-[11px] px-2.5 py-1 rounded-full font-bold">
                            <Star className="w-3 h-3 fill-black" />
                            Padrão
                          </span>
                        )}
                      </div>
                      <p className="text-white font-semibold text-[15px] mt-2 leading-snug truncate">
                        {addr.street}, {addr.number}
                        {addr.complement && ` - ${addr.complement}`}
                      </p>
                      <p className="text-zinc-400 text-sm mt-0.5 truncate">{addr.neighborhood}</p>
                      <p className="text-zinc-500 text-[13px] mt-0.5 truncate">
                        {addr.city} - {addr.state}
                        {addr.zip_code ? ` • CEP ${addr.zip_code}` : ""}
                      </p>
                    </div>
                  </div>

                  {/* Actions */}
                  <div className="mt-3 pt-3 border-t border-white/5 flex items-center justify-end gap-1">
                    <button
                      onClick={(e) => {
                        e.stopPropagation();
                        navigate({ to: `/enderecos/editar/${addr.id}` });
                      }}
                      className="flex items-center gap-1.5 text-xs font-bold text-zinc-400 hover:text-primary px-3 py-2 rounded-xl transition-colors"
                    >
                      <Edit2 className="w-4 h-4" />
                      Editar
                    </button>
                    <button
                      onClick={(e) => {
                        e.stopPropagation();
                        handleDelete(addr.id, addr.is_default);
                      }}
                      className="flex items-center gap-1.5 text-xs font-bold text-zinc-400 hover:text-red-500 px-3 py-2 rounded-xl transition-colors"
                    >
                      <Trash2 className="w-4 h-4" />
                      Excluir
                    </button>
                    <ChevronRight className="w-5 h-5 text-primary ml-1" />
                  </div>
                </div>
              );
            })}
          </div>
        )}

        <div className="mt-8">
          <Button
            onClick={() => navigate({ to: "/enderecos/novo" })}
            className="w-full bg-primary text-black hover:bg-primary/90 font-extrabold h-14 text-lg rounded-2xl shadow-[0_8px_30px_-10px_hsl(var(--primary)/0.8)] flex items-center justify-center gap-3 cursor-pointer"
          >
            <span className="w-7 h-7 rounded-full bg-black/90 text-primary flex items-center justify-center">
              <Plus className="w-4 h-4" strokeWidth={3} />
            </span>
            Adicionar endereço
          </Button>
        </div>
      </main>

      <Outlet />
    </div>
  );
}

import { createFileRoute, redirect, useNavigate, useParams } from "@tanstack/react-router";
import { useEffect, useState } from "react";
import { supabase } from "@/integrations/supabase/client";
import { ChevronLeft, Loader2, Save } from "lucide-react";
import { Button } from "@/components/ui/button";
import { Input } from "@/components/ui/input";
import { toast } from "sonner";
import { GoogleMapsAddressSelector } from "@/components/GoogleMapsAddressSelector";

export const Route = createFileRoute("/enderecos/editar/$addressId")({
  beforeLoad: async () => {
    const {
      data: { session },
    } = await supabase.auth.getSession();
    if (!session) {
      throw redirect({ to: "/login" });
    }
    return { session };
  },
  component: EditarEndereco,
  head: () => ({
    meta: [{ title: "Editar Endereço | APOIS ENTREGA" }],
  }),
});

function EditarEndereco() {
  const { addressId } = useParams({ from: "/enderecos/editar/$addressId" });
  const navigate = useNavigate();
  const [isLoading, setIsLoading] = useState(true);
  const [isSaving, setIsSaving] = useState(false);
  const [formData, setFormData] = useState({
    label: "",
    postal_code: "",
    street: "",
    number: "",
    complement: "",
    neighborhood: "",
    city: "",
    state: "",
    reference: "",
    latitude: null as number | null,
    longitude: null as number | null,
  });

  useEffect(() => {
    const fetchAddress = async () => {
      const { data, error } = await (supabase as any)
        .from("customer_addresses")
        .select("*")
        .eq("id", addressId)
        .single();

      if (error) {
        toast.error("Erro ao carregar endereço");
        navigate({ to: "/enderecos" });
      } else {
        setFormData({
          label: data.label,
          postal_code: data.postal_code,
          street: data.street,
          number: data.number,
          complement: data.complement || "",
          neighborhood: data.neighborhood,
          city: data.city,
          state: data.state,
          reference: data.reference || "",
          latitude: data.latitude,
          longitude: data.longitude,
        });
      }
      setIsLoading(false);
    };

    fetchAddress();
  }, [addressId, navigate]);

  const handleChange = (e: React.ChangeEvent<HTMLInputElement>) => {
    const { name, value } = e.target;
    setFormData((prev) => ({ ...prev, [name]: value }));
  };

  const handleSubmit = async (e: React.FormEvent) => {
    e.preventDefault();
    setIsSaving(true);

    try {
      const { error } = await (supabase as any)
        .from("customer_addresses")
        .update(formData)
        .eq("id", addressId);

      if (error) throw error;

      toast.success("Endereço atualizado!");
      await navigate({ to: "/enderecos" });
    } catch (error: any) {
      toast.error(`Erro ao salvar: ${error.message}`);
    } finally {
      setIsSaving(false);
    }
  };

  if (isLoading) {
    return (
      <div className="flex min-h-full items-center justify-center bg-black">
        <Loader2 className="w-8 h-8 animate-spin text-primary" />
      </div>
    );
  }

  const labelOptions = ["Casa", "Trabalho", "Outro"];

  return (
    <div className="absolute inset-0 z-[160] bg-black overflow-y-auto overflow-x-hidden flex flex-col w-full shadow-2xl">
      <header className="flex items-center p-4 sticky top-0 z-50 bg-black/80 backdrop-blur-lg border-b border-white/10">
        <button
          onClick={() => navigate({ to: "/enderecos" })}
          className="p-2 -ml-2 hover:bg-white/10 rounded-full transition-colors"
        >
          <ChevronLeft className="w-6 h-6" />
        </button>
        <h1 className="text-lg font-bold ml-2">Editar Endereço</h1>
      </header>

      <main className="flex-1 overflow-y-auto">
        <div className="px-6 py-4 border-b border-white/5 bg-zinc-950/50">
          <GoogleMapsAddressSelector
            initialCenter={
              formData.latitude && formData.longitude
                ? { lat: formData.latitude, lng: formData.longitude }
                : undefined
            }
            onAddressSelected={(addr) => {
              setFormData((prev) => ({
                ...prev,
                street: addr.street || prev.street,
                neighborhood: addr.neighborhood || prev.neighborhood,
                city: addr.city || prev.city,
                state: addr.state || prev.state,
                postal_code: addr.postal_code || prev.postal_code,
                number: addr.number || prev.number,
                latitude: addr.latitude ?? prev.latitude,
                longitude: addr.longitude ?? prev.longitude,
              }));
            }}
          />
        </div>

        <form onSubmit={handleSubmit} className="space-y-6 px-6 py-6 pb-24">
          <div className="space-y-3">
            <label className="text-sm font-medium text-zinc-400">Apelido do endereço</label>
            <div className="flex gap-2">
              {labelOptions.map((opt) => (
                <button
                  key={opt}
                  type="button"
                  onClick={() => setFormData((prev) => ({ ...prev, label: opt }))}
                  className={`flex-1 py-3 rounded-2xl font-bold transition-all border ${
                    formData.label === opt
                      ? "bg-primary text-black border-primary"
                      : "bg-zinc-900 text-zinc-400 border-zinc-800"
                  }`}
                >
                  {opt}
                </button>
              ))}
            </div>
          </div>

          <div className="grid grid-cols-3 gap-4">
            <div className="col-span-1 space-y-2">
              <label className="text-xs font-medium text-zinc-500 ml-1">CEP*</label>
              <Input
                name="postal_code"
                value={formData.postal_code}
                onChange={handleChange}
                className="bg-zinc-900 border-zinc-800 h-12 rounded-xl"
                required
              />
            </div>
            <div className="col-span-2 space-y-2">
              <label className="text-xs font-medium text-zinc-500 ml-1">Rua*</label>
              <Input
                name="street"
                value={formData.street}
                onChange={handleChange}
                className="bg-zinc-900 border-zinc-800 h-12 rounded-xl"
                required
              />
            </div>
          </div>

          <div className="grid grid-cols-3 gap-4">
            <div className="col-span-1 space-y-2">
              <label className="text-xs font-medium text-zinc-500 ml-1">Número*</label>
              <Input
                name="number"
                value={formData.number}
                onChange={handleChange}
                className="bg-zinc-900 border-zinc-800 h-12 rounded-xl"
                required
              />
            </div>
            <div className="col-span-2 space-y-2">
              <label className="text-xs font-medium text-zinc-500 ml-1">Complemento</label>
              <Input
                name="complement"
                value={formData.complement}
                onChange={handleChange}
                className="bg-zinc-900 border-zinc-800 h-12 rounded-xl"
              />
            </div>
          </div>

          <div className="space-y-2">
            <label className="text-xs font-medium text-zinc-500 ml-1">Bairro*</label>
            <Input
              name="neighborhood"
              value={formData.neighborhood}
              onChange={handleChange}
              className="bg-zinc-900 border-zinc-800 h-12 rounded-xl"
              required
            />
          </div>

          <div className="grid grid-cols-4 gap-4">
            <div className="col-span-3 space-y-2">
              <label className="text-xs font-medium text-zinc-500 ml-1">Cidade*</label>
              <Input
                name="city"
                value={formData.city}
                onChange={handleChange}
                className="bg-zinc-900 border-zinc-800 h-12 rounded-xl"
                required
              />
            </div>
            <div className="col-span-1 space-y-2">
              <label className="text-xs font-medium text-zinc-500 ml-1">UF*</label>
              <Input
                name="state"
                maxLength={2}
                value={formData.state}
                onChange={handleChange}
                className="bg-zinc-900 border-zinc-800 h-12 rounded-xl uppercase text-center"
                required
              />
            </div>
          </div>

          <div className="space-y-2">
            <label className="text-xs font-medium text-zinc-500 ml-1">Ponto de referência</label>
            <Input
              name="reference"
              value={formData.reference}
              onChange={handleChange}
              className="bg-zinc-900 border-zinc-800 h-12 rounded-xl"
            />
          </div>

          <div className="sticky bottom-0 left-0 right-0 p-6 bg-gradient-to-t from-black via-black to-transparent pt-10">
            <Button
              type="submit"
              disabled={isSaving}
              className="w-full bg-primary text-black hover:bg-primary/90 font-bold h-14 text-lg rounded-2xl shadow-xl flex items-center justify-center gap-2"
            >
              {isSaving ? (
                <Loader2 className="w-6 h-6 animate-spin" />
              ) : (
                <>
                  <Save className="w-5 h-5" />
                  Atualizar endereço
                </>
              )}
            </Button>
          </div>
        </form>
      </main>
    </div>
  );
}

import { createFileRoute, redirect, useNavigate } from "@tanstack/react-router";
import { useState, useEffect } from "react";
import { supabase } from "@/integrations/supabase/client";
import { ChevronLeft, Loader2, Save, MapPin, Home, Briefcase } from "lucide-react";
import { Button } from "@/components/ui/button";
import { Input } from "@/components/ui/input";
import { toast } from "sonner";
import { GoogleMapsAddressSelector } from "@/components/GoogleMapsAddressSelector";

export const Route = createFileRoute("/enderecos/novo")({
  beforeLoad: async () => {
    const {
      data: { session },
    } = await supabase.auth.getSession();
    if (!session) {
      throw redirect({ to: "/login" });
    }
    return { session };
  },
  component: NovoEndereco,
  head: () => ({
    meta: [{ title: "Novo Endereço | APOIS ENTREGA" }],
  }),
});

function NovoEndereco() {
  const navigate = useNavigate();
  const [isLoading, setIsLoading] = useState(false);
  const [formData, setFormData] = useState({
    label: "Casa",
    postal_code: "",
    street: "",
    number: "",
    complement: "",
    neighborhood: "",
    city: "",
    state: "",
    reference: "",
    latitude: null as number | null,
    longitude: null as number | null,
  });

  useEffect(() => {
    window.scrollTo(0, 0);
  }, []);

  const handleChange = (e: React.ChangeEvent<HTMLInputElement>) => {
    const { name, value } = e.target;
    setFormData((prev) => ({ ...prev, [name]: value }));
  };

  const handleCEPBlur = async () => {
    const cep = formData.postal_code.replace(/\D/g, "");
    if (cep.length !== 8) return;

    try {
      const response = await fetch(`https://viacep.com.br/ws/${cep}/json/`);
      const data = await response.json();

      if (!data.erro) {
        setFormData((prev) => ({
          ...prev,
          street: data.logradouro || prev.street,
          neighborhood: data.bairro || prev.neighborhood,
          city: data.localidade || prev.city,
          state: data.uf || prev.state,
        }));
      }
    } catch (error) {
      console.error("CEP fetch error:", error);
    }
  };

  const handleSubmit = async (e: React.FormEvent) => {
    e.preventDefault();

    // Validation
    const required = ["postal_code", "street", "number", "neighborhood", "city", "state"];
    for (const field of required) {
      if (!formData[field as keyof typeof formData]) {
        toast.error(`O campo ${field} é obrigatório`);
        return;
      }
    }

    if (formData.state.length !== 2) {
      toast.error("O estado (UF) deve ter exatamente 2 letras");
      return;
    }

    setIsLoading(true);

    try {
      const {
        data: { user },
      } = await supabase.auth.getUser();
      if (!user) throw new Error("Usuário não autenticado");

      // Check if it's the first address
      const { count } = await (supabase as any)
        .from("customer_addresses")
        .select("*", { count: "exact", head: true })
        .eq("user_id", user.id);

      const isFirst = count === 0;

      const { error } = await (supabase as any).from("customer_addresses").insert({
        ...formData,
        user_id: user.id,
        is_default: isFirst,
      });

      if (error) throw error;

      toast.success("Endereço salvo com sucesso!");
      await navigate({ to: "/enderecos" });
    } catch (error: any) {
      toast.error(`Erro ao salvar: ${error.message}`);
    } finally {
      setIsLoading(false);
    }
  };

  const labelOptions = [
    { value: "Casa", Icon: Home },
    { value: "Trabalho", Icon: Briefcase },
    { value: "Outro", Icon: MapPin },
  ];

  return (
    <div className="absolute inset-0 z-[160] bg-black overflow-y-auto overflow-x-hidden flex flex-col w-full shadow-2xl">
      <header className="flex items-center p-4 sticky top-0 z-50 bg-black/90 backdrop-blur-xl border-b border-white/10">
        <button
          onClick={() => navigate({ to: "/enderecos" })}
          className="w-10 h-10 flex items-center justify-center -ml-1 rounded-full bg-white/5 border border-white/10 text-primary hover:bg-white/10 transition-colors active:scale-95"
        >
          <ChevronLeft className="w-5 h-5" />
        </button>
        <h1 className="text-[17px] font-extrabold ml-3 tracking-tight">Novo Endereço</h1>
      </header>

      <main className="flex-1 overflow-y-auto">
        <div className="px-5 py-5 border-b border-white/5 bg-gradient-to-b from-zinc-950 to-black">
          <GoogleMapsAddressSelector
            onAddressSelected={(addr) => {
              setFormData((prev) => ({
                ...prev,
                street: addr.street || prev.street,
                neighborhood: addr.neighborhood || prev.neighborhood,
                city: addr.city || prev.city,
                state: addr.state || prev.state,
                postal_code: addr.postal_code || prev.postal_code,
                number: addr.number || prev.number,
                latitude: addr.latitude ?? prev.latitude,
                longitude: addr.longitude ?? prev.longitude,
              }));
            }}
          />
        </div>

        <form onSubmit={handleSubmit} className="space-y-5 px-5 py-5 pb-40">
          <div className="space-y-3">
            <label className="text-[11px] font-bold uppercase tracking-widest text-zinc-500">
              Tipo do endereço
            </label>
            <div className="flex gap-2">
              {labelOptions.map(({ value, Icon }) => (
                <button
                  key={value}
                  type="button"
                  onClick={() => setFormData((prev) => ({ ...prev, label: value }))}
                  className={`flex-1 py-3 rounded-2xl font-bold text-sm transition-all border flex flex-col items-center gap-1.5 active:scale-[0.97] ${
                    formData.label === value
                      ? "bg-primary text-black border-primary shadow-[0_6px_20px_-6px_hsl(var(--primary))]"
                      : "bg-zinc-900 text-zinc-400 border-zinc-800"
                  }`}
                >
                  <Icon className="w-5 h-5" />
                  {value}
                </button>
              ))}
            </div>
          </div>

          <div className="grid grid-cols-3 gap-4">
            <div className="col-span-1 space-y-2">
              <label className="text-xs font-medium text-zinc-500 ml-1">CEP*</label>
              <Input
                name="postal_code"
                placeholder="00000-000"
                value={formData.postal_code}
                onChange={handleChange}
                onBlur={handleCEPBlur}
                className="bg-zinc-900 border-zinc-800 h-12 rounded-xl focus:ring-primary text-white"
                required
              />
            </div>
            <div className="col-span-2 space-y-2">
              <label className="text-xs font-medium text-zinc-500 ml-1">Rua*</label>
              <Input
                name="street"
                placeholder="Nome da rua"
                value={formData.street}
                onChange={handleChange}
                className="bg-zinc-900 border-zinc-800 h-12 rounded-xl focus:ring-primary text-white"
                required
              />
            </div>
          </div>

          <div className="grid grid-cols-3 gap-4">
            <div className="col-span-1 space-y-2">
              <label className="text-xs font-medium text-zinc-500 ml-1">Número*</label>
              <Input
                name="number"
                placeholder="123"
                value={formData.number}
                onChange={handleChange}
                className="bg-zinc-900 border-zinc-800 h-12 rounded-xl focus:ring-primary text-white"
                required
              />
            </div>
            <div className="col-span-2 space-y-2">
              <label className="text-xs font-medium text-zinc-500 ml-1">Complemento</label>
              <Input
                name="complement"
                placeholder="Apto, Bloco, etc."
                value={formData.complement}
                onChange={handleChange}
                className="bg-zinc-900 border-zinc-800 h-12 rounded-xl focus:ring-primary text-white"
              />
            </div>
          </div>

          <div className="space-y-2">
            <label className="text-xs font-medium text-zinc-500 ml-1">Bairro*</label>
            <Input
              name="neighborhood"
              placeholder="Nome do bairro"
              value={formData.neighborhood}
              onChange={handleChange}
              className="bg-zinc-900 border-zinc-800 h-12 rounded-xl focus:ring-primary text-white"
              required
            />
          </div>

          <div className="grid grid-cols-4 gap-4">
            <div className="col-span-3 space-y-2">
              <label className="text-xs font-medium text-zinc-500 ml-1">Cidade*</label>
              <Input
                name="city"
                placeholder="Sua cidade"
                value={formData.city}
                onChange={handleChange}
                className="bg-zinc-900 border-zinc-800 h-12 rounded-xl focus:ring-primary text-white"
                required
              />
            </div>
            <div className="col-span-1 space-y-2">
              <label className="text-xs font-medium text-zinc-500 ml-1">UF*</label>
              <Input
                name="state"
                placeholder="SP"
                maxLength={2}
                value={formData.state}
                onChange={handleChange}
                className="bg-zinc-900 border-zinc-800 h-12 rounded-xl focus:ring-primary uppercase text-center text-white"
                required
              />
            </div>
          </div>

          <div className="space-y-2">
            <label className="text-xs font-medium text-zinc-500 ml-1">Ponto de referência</label>
            <Input
              name="reference"
              placeholder="Próximo ao..."
              value={formData.reference}
              onChange={handleChange}
