function MerchantReviewState({
  merchant,
  documents,
  busyAction,
  onUpload,
  onResubmit,
  onRefresh,
  refreshing,
  onLogout,
}: any) {
  const requiredDocs = [
    { type: "documento_empresa", label: "Documento da empresa (CNPJ/MEI)" },
    { type: "responsavel", label: "Documento do responsável" },
    { type: "comprovante_endereco", label: "Comprovante de endereço" },
  ];
  return (
    <div className="min-h-dvh bg-black p-4 text-white md:p-8">
      <div className="mx-auto max-w-4xl">
        <div className="flex items-center justify-between gap-4">
          <div>
            <p className="font-black text-primary">APOIS ENTREGA</p>
            <h1 className="text-2xl font-black">{merchant.name}</h1>
          </div>
          <button type="button" onClick={onLogout} className="text-sm font-bold text-zinc-500">
            Sair
          </button>
        </div>
        <div className="mt-8 rounded-3xl border border-zinc-900 bg-zinc-950 p-6">
          <div className="flex flex-wrap items-center justify-between gap-4">
            <div>
              <p className="text-xs font-bold uppercase text-zinc-500">Situação do cadastro</p>
              <p className="mt-1 text-xl font-black uppercase text-primary">
                {merchant.approval_status.replaceAll("_", " ")}
              </p>
            </div>
            <Button
              variant="outline"
              onClick={onRefresh}
              disabled={refreshing}
              className="border-zinc-800 bg-black"
            >
              <RefreshCw className={`mr-2 h-4 w-4 ${refreshing ? "animate-spin" : ""}`} />
              Atualizar
            </Button>
          </div>
          {merchant.rejection_reason ? (
            <div className="mt-4 rounded-xl border border-red-500/20 bg-red-500/10 p-4 text-sm text-red-300">
              <strong>Motivo:</strong> {merchant.rejection_reason}
            </div>
          ) : null}
          <div className="mt-6 grid gap-3 md:grid-cols-3">
            {requiredDocs.map((item) => {
              const doc = documents.find((document: any) => document.document_type === item.type);
              return (
                <label key={item.type} className="rounded-2xl border border-zinc-800 bg-black p-4">
                  <p className="text-sm font-bold">{item.label}</p>
                  <p
                    className={`mt-1 text-xs font-black uppercase ${doc?.status === "approved" ? "text-emerald-400" : doc?.status === "rejected" ? "text-red-400" : "text-primary"}`}
                  >
                    {doc?.status ?? "Não enviado"}
                  </p>
                  {doc?.rejection_reason ? (
                    <p className="mt-2 text-xs text-red-300">{doc.rejection_reason}</p>
                  ) : null}
                  <input
                    type="file"
                    accept="image/jpeg,image/png,image/webp,application/pdf"
                    className="mt-4 block w-full text-xs text-zinc-500 file:mr-2 file:rounded-lg file:border-0 file:bg-primary file:px-3 file:py-2 file:font-bold file:text-black"
                    disabled={busyAction === `doc:${item.type}`}
                    onChange={(e) => {
                      const file = e.target.files?.[0];
                      if (file) void onUpload(item.type, file);
                    }}
                  />
                </label>
              );
            })}
          </div>
          {merchant.approval_status === "rejected" ? (
            <Button
              onClick={onResubmit}
              disabled={busyAction === "resubmit"}
              className="mt-6 w-full"
            >
              Reenviar para análise
            </Button>
          ) : null}
          <p className="mt-6 text-sm text-zinc-500">
            O painel de pedidos, cardápio e financeiro será liberado automaticamente após a
            aprovação.
          </p>
        </div>
      </div>
    </div>
  );
}

function OrderRow({ order, busy, onTransition, onReject, detailed = false }: any) {
  const nextActions: Array<{ status: string; label: string }> =
    order.status === "confirmed"
      ? [
          { status: "accepted", label: "Aceitar" },
          { status: "preparing", label: "Aceitar e preparar" },
        ]
      : order.status === "accepted"
        ? [{ status: "preparing", label: "Iniciar preparo" }]
        : order.status === "preparing"
          ? [{ status: "ready", label: "Marcar como pronto" }]
          : [];
  const canReject = ["confirmed", "accepted", "preparing"].includes(order.status);
  return (
    <div className="rounded-2xl border border-zinc-900 bg-black p-4">
      <div className="flex flex-wrap items-start justify-between gap-3">
        <div>
          <p className="text-lg font-black">Pedido #{order.order_number}</p>
          <p className="text-xs text-zinc-500">
            {dateTime(order.created_at)} · {order.order_items?.length ?? 0} item(ns)
          </p>
        </div>
        <div className="text-right">
          <p className="font-black text-primary">{money(order.total)}</p>
          <p className="text-[10px] font-black uppercase text-zinc-500">
            {order.status} · {order.payment_status}
          </p>
        </div>
      </div>
      {detailed ? (
        <div className="mt-3 space-y-1 border-t border-zinc-900 pt-3">
          {order.order_items?.map((item: any) => (
            <p key={item.id} className="text-sm text-zinc-400">
              {item.quantity}x {item.product_name} — {money(item.line_total)}
            </p>
          ))}
          {order.observation ? (
            <p className="mt-2 rounded-lg bg-zinc-950 p-2 text-xs text-zinc-400">
              Obs.: {order.observation}
            </p>
          ) : null}
        </div>
      ) : null}
      {nextActions.length > 0 || canReject ? (
        <div className="mt-4 flex flex-wrap gap-2">
          {nextActions.map((action) => (
            <Button
              type="button"
              size="sm"
              key={action.status}
              disabled={busy || order.payment_status !== "paid"}
              onClick={() => void onTransition(order.id, action.status)}
            >
              {busy ? (
                <Loader2 className="mr-1 h-3 w-3 animate-spin" />
              ) : (
                <PackageCheck className="mr-1 h-3 w-3" />
              )}
              {action.label}
            </Button>
          ))}
          {canReject ? (
            <Button
              type="button"
              size="sm"
              variant="outline"
              disabled={busy}
              onClick={() => void onReject(order.id)}
              className="border-red-500/20 text-red-400"
            >
              Cancelar
            </Button>
          ) : null}
        </div>
      ) : null}
    </div>
  );
}

function Field({
  value,
  onChange,
  placeholder,
  type = "text",
  required = false,
}: {
  value: string;
  onChange: (value: string) => void;
  placeholder: string;
  type?: string;
  required?: boolean;
}) {
  return (
    <input
      value={value}
      onChange={(event) => onChange(event.target.value)}
      placeholder={placeholder}
      type={type}
      required={required}
      step={type === "number" ? "0.01" : undefined}
      min={type === "number" ? "0" : undefined}
      className="mt-1 w-full rounded-xl border border-zinc-800 bg-black px-3 py-3 text-sm text-white outline-none focus:border-primary"
    />
  );
}

import { createFileRoute, redirect, useNavigate, useParams } from "@tanstack/react-router";
import { ArrowLeft, Star, MessageSquare } from "lucide-react";
import { useEffect, useState } from "react";
import { supabase } from "@/integrations/supabase/client";
import { getLocalOrderById, getLocalOrders, LocalOrder, saveLocalOrders } from "@/lib/local-orders";

export const Route = createFileRoute("/pedido/$orderId/avaliar")({
  component: RateOrderPage,
});

function RateOrderPage() {
  const navigate = useNavigate();
  const { orderId } = useParams({ from: "/pedido/$orderId/avaliar" });
  const [order, setOrder] = useState<LocalOrder | null>(null);
  const [loading, setLoading] = useState(true);
  const [merchantRating, setMerchantRating] = useState(0);
  const [deliveryRating, setDeliveryRating] = useState(0);
  const [comment, setComment] = useState("");

  useEffect(() => {
    const fetchOrder = async () => {
      const {
        data: { user },
      } = await supabase.auth.getUser();
      if (!user) {
        setLoading(false);
        return;
      }

      const foundOrder = getLocalOrderById(user.id, orderId);

      if (foundOrder) {
        if (foundOrder.status !== "entregue") {
          navigate({ to: `/pedido/${orderId}` });
          return;
        }
        setOrder(foundOrder);
      }
      setLoading(false);
    };

    fetchOrder();
  }, [orderId]);

  const handleSave = async () => {
    const {
      data: { user },
    } = await supabase.auth.getUser();
    if (!user) return;

    const orders = getLocalOrders(user.id);
    const updatedOrders = orders.map((o) =>
      o.id === orderId
        ? { ...o, rating: { merchant: merchantRating, delivery: deliveryRating, comment } }
        : o,
    );
    saveLocalOrders(user.id, updatedOrders);
    navigate({ to: `/pedido/${orderId}` });
  };

  if (loading) return null;
  if (!order) {
    return (
      <div className="flex h-screen w-full flex-col items-center justify-center bg-black p-6 text-center text-white">
        <h2 className="text-xl font-bold mb-4">Pedido não encontrado</h2>
        <button
          onClick={() => navigate({ to: "/pedidos" })}
          className="bg-primary text-black px-6 py-3 rounded-xl font-bold uppercase shadow-lg shadow-primary/20 active:scale-95 transition-transform"
        >
          Voltar para Meus Pedidos
        </button>
      </div>
    );
  }

  const StarRating = ({ value, onChange }: { value: number; onChange: (v: number) => void }) => (
    <div className="flex gap-2">
      {[1, 2, 3, 4, 5].map((star) => (
        <button key={star} onClick={() => onChange(star)} className="focus:outline-none">
          <Star
            className={`h-8 w-8 ${star <= value ? "fill-primary text-primary" : "text-zinc-800"}`}
          />
        </button>
      ))}
    </div>
  );

  return (
    <div className="flex h-screen w-full flex-col bg-black text-white overflow-hidden">
      <header className="sticky top-0 z-50 flex items-center gap-4 bg-black/80 p-4 backdrop-blur-lg border-b border-zinc-900">
        <button onClick={() => window.history.back()} className="p-2 rounded-full bg-zinc-900">
          <ArrowLeft />
        </button>
        <h1 className="text-lg font-bold">Avaliar pedido</h1>
      </header>

      <main className="flex-1 overflow-y-auto p-6 space-y-8">
        <div className="text-center">
          <img
            src={order.merchant.logo}
            className="w-20 h-20 rounded-2xl mx-auto mb-3 object-cover ring-1 ring-white/10"
            alt=""
          />
          <h2 className="text-xl font-bold">{order.merchant.name}</h2>
          <p className="text-zinc-500 text-sm">Como foi sua experiência com este pedido?</p>
        </div>

        <section className="space-y-4">
          <div className="p-6 rounded-2xl bg-zinc-950 border border-zinc-900 space-y-4">
            <h3 className="text-sm font-bold uppercase tracking-wider text-zinc-500">
              Estabelecimento
            </h3>
            <StarRating value={merchantRating} onChange={setMerchantRating} />
          </div>

          <div className="p-6 rounded-2xl bg-zinc-950 border border-zinc-900 space-y-4">
            <h3 className="text-sm font-bold uppercase tracking-wider text-zinc-500">Entrega</h3>
            <StarRating value={deliveryRating} onChange={setDeliveryRating} />
          </div>

          <div className="p-6 rounded-2xl bg-zinc-950 border border-zinc-900 space-y-4">
            <div className="flex items-center gap-2 mb-2">
              <MessageSquare className="h-4 w-4 text-zinc-500" />
              <h3 className="text-sm font-bold uppercase tracking-wider text-zinc-500">
                Comentário opcional
              </h3>
            </div>
            <textarea
              value={comment}
              onChange={(e) => setComment(e.target.value)}
              placeholder="Conte-nos um pouco mais sobre o que achou..."
              className="w-full h-32 bg-zinc-900 rounded-xl p-4 text-sm focus:outline-none ring-1 ring-white/5"
            />
          </div>
        </section>
      </main>

      <footer className="p-4 bg-black border-t border-zinc-900">
        <button
          onClick={handleSave}
          disabled={!merchantRating || !deliveryRating}
          className="w-full bg-primary disabled:opacity-50 disabled:grayscale text-black font-black py-4 rounded-xl uppercase shadow-lg shadow-primary/20 active:scale-95 transition-transform"
        >
          Enviar avaliação
        </button>
      </footer>
    </div>
  );
}

import { createFileRoute, useNavigate, useParams } from "@tanstack/react-router";
import {
  ArrowLeft,
  MapPin,
  CheckCircle2,
  Bike,
  PackageCheck,
  UtensilsCrossed,
  Star,
  Loader2,
  XCircle,
} from "lucide-react";
import { useCallback, useEffect, useState } from "react";
import { supabase } from "@/integrations/supabase/client";
import { toast } from "sonner";

export const Route = createFileRoute("/pedido/$orderId/")({
  component: OrderDetailsPage,
  head: () => ({ meta: [{ title: "Detalhes do Pedido | APOIS ENTREGA" }] }),
});

function OrderDetailsPage() {
  const navigate = useNavigate();
  const { orderId } = useParams({ from: "/pedido/$orderId/" });
  const [order, setOrder] = useState<any | null>(null);
  const [loading, setLoading] = useState(true);
  const [cancelling, setCancelling] = useState(false);

  const fetchOrder = useCallback(async () => {
    const { data, error } = await supabase
      .from("orders")
      .select("*, merchants (*), order_items (*)")
      .eq("id", orderId)
      .single();
    if (error) {
      toast.error("Não foi possível carregar os detalhes deste pedido.");
      setOrder(null);
    } else {
      setOrder(data);
    }
    setLoading(false);
  }, [orderId]);

  useEffect(() => {
    void fetchOrder();
    const channel = supabase
      .channel(`order_status_${orderId}`)
      .on(
        "postgres_changes",
        { event: "UPDATE", schema: "public", table: "orders", filter: `id=eq.${orderId}` },
        (payload) => {
          setOrder((previous: any) => (previous ? { ...previous, ...payload.new } : null));
        },
      )
      .subscribe();
    return () => {
      void supabase.removeChannel(channel);
    };
  }, [orderId, fetchOrder]);

  const cancelOrder = async () => {
    if (!order || cancelling) return;
    const reason = window.prompt("Por que você deseja cancelar este pedido?")?.trim();
    if (!reason) return;
    if (
      !window.confirm(
        "Confirma o cancelamento? Depois de cancelado, o pedido não seguirá para preparo/entrega.",
      )
    )
      return;

    setCancelling(true);
    try {
      const { data, error } = await supabase.rpc("customer_cancel_order", {
        _order_id: order.id,
        _reason: reason,
      });
      if (error) throw error;
      const refundId = (data as any)?.refund_id ?? null;
      if (refundId) {
        const { error: refundError } = await supabase.functions.invoke("process-refund", {
          body: { refundId },
        });
        if (refundError)
          toast.warning(
            "Pedido cancelado. O estorno foi registrado e continuará pendente para nova tentativa.",
          );
        else toast.success("Pedido cancelado e estorno processado.");
      } else {
        toast.success("Pedido cancelado.");
      }
      await fetchOrder();
    } catch (error: any) {
      toast.error(error?.message || "Não foi possível cancelar este pedido.");
    } finally {
      setCancelling(false);
    }
  };

  if (loading)
    return (
      <div className="flex h-screen w-full items-center justify-center bg-black">
        <Loader2 className="h-8 w-8 animate-spin text-primary" />
      </div>
    );

  if (!order) {
    return (
      <div className="flex h-screen w-full flex-col items-center justify-center bg-black p-6 text-center text-white">
        <h2 className="mb-4 text-xl font-bold">Pedido não encontrado</h2>
        <button
          type="button"
          onClick={() => navigate({ to: "/pedidos" })}
          className="rounded-xl bg-primary px-6 py-3 font-bold uppercase text-black shadow-lg shadow-primary/20 transition-transform active:scale-95"
        >
          Voltar para Meus Pedidos
        </button>
      </div>
    );
  }

  const getStatusStep = (status: string) => {
    switch (status) {
      case "confirmed":
      case "accepted":
        return 0;
      case "preparing":
        return 1;
      case "ready":
      case "ready_for_pickup":
      case "searching_driver":
      case "driver_assigned":
      case "driver_arriving_store":
        return 2;
      case "picked_up":
      case "out_for_delivery":
      case "on_the_way":
        return 3;
      case "delivered":
        return 4;
      default:
        return -1;
    }
  };

  const currentStepIdx = getStatusStep(order.status);
  const isCancelled = order.status === "cancelled";
  const isRefunded = order.status === "refunded" || order.payment_status === "refunded";
  const canCancel = ["created", "pending_payment", "paid", "confirmed"].includes(order.status);
  const stepStatus = (index: number) => {
    if (currentStepIdx < 0) return "pending";
    if (order.status === "delivered" && index <= currentStepIdx) return "completed";
    if (index < currentStepIdx) return "completed";
    if (index === currentStepIdx) return "current";
    return "pending";
  };

  const steps = [
    { label: "Pedido confirmado", icon: CheckCircle2, status: stepStatus(0) },
    { label: "Estabelecimento preparando", icon: UtensilsCrossed, status: stepStatus(1) },
    { label: "Pedido pronto", icon: PackageCheck, status: stepStatus(2) },
    { label: "Saiu para entrega", icon: Bike, status: stepStatus(3) },
    { label: "Entregue", icon: CheckCircle2, status: stepStatus(4) },
  ];

  let deliveryAddress: any = order.delivery_address;
  if (typeof deliveryAddress === "string") {
    try {
      deliveryAddress = JSON.parse(deliveryAddress);
    } catch {
      deliveryAddress = {};
    }
  }

  return (
    <div className="flex h-screen w-full flex-col overflow-hidden bg-black text-white">
      <header className="sticky top-0 z-50 flex items-center gap-4 border-b border-zinc-900 bg-black/80 p-4 backdrop-blur-lg">
        <button
          type="button"
          onClick={() => navigate({ to: "/pedidos" })}
          className="rounded-full bg-zinc-900 p-2"
        >
          <ArrowLeft />
        </button>
        <div>
          <h1 className="text-lg font-bold">Pedido #{order.order_number}</h1>
          <p className="text-[10px] font-black uppercase tracking-widest text-zinc-500">
            {order.merchants?.name}
          </p>
        </div>
      </header>

      <main className="flex-1 space-y-6 overflow-y-auto p-4 pb-20">
        {isCancelled || isRefunded ? (
          <section className="rounded-2xl border border-zinc-800 bg-zinc-950 p-4">
            <p className="text-sm font-black uppercase text-zinc-300">
              {isRefunded ? "Pedido reembolsado" : "Pedido cancelado"}
            </p>
            <p className="mt-1 text-xs text-zinc-500">
              {isRefunded
                ? "O pagamento deste pedido foi reembolsado."
                : order.payment_status === "paid"
                  ? "O pedido foi cancelado. Se houver estorno pendente, ele será conciliado pelo sistema."
                  : "Este pedido foi cancelado e não seguirá para entrega."}
            </p>
          </section>
        ) : (
          <section className="rounded-2xl border border-zinc-900 bg-zinc-950 p-6">
            <div className="space-y-6">
              {steps.map((step, index) => {
                const Icon = step.icon;
                return (
                  <div key={step.label} className="relative flex gap-4">
                    {index !== steps.length - 1 ? (
                      <div
                        className={`absolute left-4 top-8 h-10 w-[2px] ${step.status === "completed" ? "bg-primary" : "bg-zinc-800"}`}
                      />
                    ) : null}
                    <div
                      className={`grid h-8 w-8 shrink-0 place-items-center rounded-full ring-2 ring-black ${step.status === "completed" ? "bg-primary text-black" : step.status === "current" ? "bg-zinc-800 text-primary ring-primary/20" : "bg-zinc-900 text-zinc-700"}`}
                    >
                      <Icon className="h-4 w-4" />
                    </div>
                    <div className="flex-1 pt-1">
                      <p
                        className={`text-sm font-bold ${step.status === "pending" ? "text-zinc-700" : "text-white"}`}
                      >
                        {step.label}
                      </p>
                      {step.status === "current" ? (
                        <p className="animate-pulse text-[10px] font-bold text-primary">
                          EM ANDAMENTO
                        </p>
                      ) : null}
                    </div>
                  </div>
                );
              })}
            </div>
          </section>
        )}

        {canCancel ? (
          <button
            type="button"
            disabled={cancelling}
            onClick={cancelOrder}
            className="flex w-full items-center justify-center gap-2 rounded-xl border border-red-500/20 bg-red-500/5 py-4 font-bold text-red-400 disabled:opacity-50"
          >
            {cancelling ? (
              <Loader2 className="h-5 w-5 animate-spin" />
            ) : (
              <XCircle className="h-5 w-5" />
            )}
            {cancelling ? "Cancelando..." : "Cancelar pedido"}
          </button>
        ) : null}

        {order.status === "delivered" ? (
          <button
            type="button"
            onClick={() => navigate({ to: `/pedido/${orderId}/avaliar` })}
            className="flex w-full items-center justify-center gap-2 rounded-xl border border-primary/20 bg-primary/10 py-4 font-bold text-primary shadow-lg shadow-primary/5 transition-transform active:scale-95"
          >
            <Star className="h-5 w-5 fill-primary" />
            Avaliar pedido
          </button>
        ) : null}

        <section className="space-y-4 rounded-2xl border border-zinc-900 bg-zinc-950 p-4">
          <h3 className="text-sm font-black uppercase tracking-wider text-zinc-500">
            Resumo do pedido
          </h3>
          <div className="space-y-3">
            {order.order_items?.map((item: any) => (
              <div key={item.id} className="space-y-1">
                <div className="flex justify-between text-sm">
                  <span className="text-zinc-300">
                    {item.quantity}x {item.product_name}
                  </span>
                  <span className="font-bold">
                    R$ {Number(item.line_total).toFixed(2).replace(".", ",")}
                  </span>
                </div>
                {item.selected_options ? (
                  <p className="text-[10px] text-zinc-500">
                    {Array.isArray(item.selected_options)
                      ? item.selected_options.map((option: any) => option.optionName).join(" • ")
                      : typeof item.selected_options === "object"
                        ? Object.values(item.selected_options)
                            .map((option: any) => option.optionName)
                            .join(" • ")
                        : ""}
                  </p>
                ) : null}
              </div>
            ))}
          </div>
          <div className="space-y-2 border-t border-zinc-900 pt-3">
            <div className="flex justify-between text-xs text-zinc-500">
              <span>Subtotal</span>
              <span>R$ {Number(order.subtotal).toFixed(2).replace(".", ",")}</span>
            </div>
            <div className="flex justify-between text-xs text-zinc-500">
              <span>Taxa de entrega</span>
              <span>R$ {Number(order.delivery_fee).toFixed(2).replace(".", ",")}</span>
            </div>
            <div className="flex justify-between pt-2 text-lg font-black text-primary">
              <span>Total</span>
              <span>R$ {Number(order.total).toFixed(2).replace(".", ",")}</span>
            </div>
          </div>
        </section>

        <section className="flex gap-4 rounded-2xl border border-zinc-900 bg-zinc-950 p-4">
          <div className="grid h-10 w-10 shrink-0 place-items-center rounded-xl bg-zinc-900">
            <MapPin className="h-5 w-5 text-primary" />
          </div>
          <div>
            <p className="text-xs font-bold uppercase text-zinc-500">Endereço de entrega</p>
            <p className="mt-0.5 text-sm font-bold">
              {deliveryAddress?.street || "—"}, {deliveryAddress?.number || "s/n"}
            </p>
            <p className="text-[11px] text-zinc-500">
              {deliveryAddress?.label ? `${deliveryAddress.label} • ` : ""}
              {deliveryAddress?.neighborhood || ""}
            </p>
          </div>
        </section>

        <div className="grid grid-cols-2 gap-4">
          <section className="rounded-2xl border border-zinc-900 bg-zinc-950 p-4">
            <p className="mb-1 text-[10px] font-bold uppercase text-zinc-500">Pagamento</p>
            <p className="text-sm font-bold uppercase">
              {order.payment_method} · {order.payment_status}
            </p>
          </section>
          <section className="rounded-2xl border border-zinc-900 bg-zinc-950 p-4">
            <p className="mb-1 text-[10px] font-bold uppercase text-zinc-500">Data</p>
            <p className="text-sm font-bold">
              {new Date(order.created_at).toLocaleDateString("pt-BR")}
            </p>
          </section>
        </div>
      </main>
    </div>
  );
}

