import { supabase } from "@/integrations/supabase/client";
import { useEffect, useState } from "react";

export const Route = createFileRoute("/pedidos")({
  beforeLoad: async ({ location }) => {
    const {
      data: { session },
    } = await supabase.auth.getSession();
    if (!session) {
      throw redirect({
        to: "/login",
        search: {
          redirect: location.href,
        },
      });
    }
    return { session };
  },
  component: PedidosPage,
  head: () => ({
    meta: [{ title: "Meus Pedidos | APOIS ENTREGA" }],
  }),
});

function PedidosPage() {
  const navigate = useNavigate();
  const { totalItems } = useCart();
  const [orders, setOrders] = useState<any[]>([]);
  const [loading, setLoading] = useState(true);
  const [loadError, setLoadError] = useState<string | null>(null);

  const fetchOrders = async () => {
    setLoading(true);
    setLoadError(null);

    const {
      data: { user },
      error: userError,
    } = await supabase.auth.getUser();
    if (userError || !user) {
      console.error("Erro ao identificar cliente para carregar pedidos:", userError);
      setOrders([]);
      setLoadError("Não foi possível identificar sua sessão. Tente novamente.");
      setLoading(false);
      return;
    }

    const { data, error } = await supabase
      .from("orders" as any)
      .select("*, merchants(name, logo_url)")
      .eq("customer_user_id", user.id)
      .order("created_at", { ascending: false });

    if (error) {
      console.error("Erro ao carregar pedidos reais:", error);
      setOrders([]);
      setLoadError("Não foi possível carregar seus pedidos agora.");
    } else {
      setOrders(data || []);
    }

    setLoading(false);
  };

  useEffect(() => {
    void fetchOrders();
  }, []);

  return (
    <div className="flex h-screen w-full flex-col bg-black text-white overflow-hidden relative">
      <header className="sticky top-0 z-50 flex items-center justify-between p-4 bg-black/80 backdrop-blur-lg border-b border-zinc-900">
        <button
          onClick={() => navigate({ to: "/inicio" })}
          className="p-2 rounded-full bg-zinc-900"
        >
          <ArrowLeft />
        </button>
        <h1 className="text-xl font-bold">Meus Pedidos</h1>
        <button
          onClick={() => navigate({ to: "/sacola" })}
          className="relative p-2 rounded-full bg-zinc-900"
        >
          <ShoppingBag />
          {totalItems > 0 && (
            <span className="absolute -top-1 -right-1 bg-primary text-black text-[10px] font-bold w-4 h-4 flex items-center justify-center rounded-full">
              {totalItems}
            </span>
          )}
        </button>
      </header>

      <main className="flex-1 overflow-y-auto p-4 pb-24 scrollbar-none space-y-4">
        {loading ? (
          <div className="h-full flex items-center justify-center">
            <Loader2 className="h-8 w-8 animate-spin text-primary" />
          </div>
        ) : loadError ? (
          <div className="h-full flex flex-col items-center justify-center text-center py-20">
            <div className="w-20 h-20 bg-zinc-900 rounded-full flex items-center justify-center mb-4">
              <ShoppingBag className="w-8 h-8 text-zinc-600" />
            </div>
            <h2 className="text-lg font-bold">Não foi possível carregar seus pedidos</h2>
            <p className="text-zinc-500 text-sm mt-2 max-w-xs">{loadError}</p>
            <button
              type="button"
              onClick={() => void fetchOrders()}
              className="mt-6 flex items-center gap-2 rounded-xl bg-primary px-5 py-3 font-black uppercase text-black active:scale-95 transition-transform"
            >
              <RefreshCw className="h-4 w-4" />
              Tentar novamente
            </button>
          </div>
        ) : orders.length > 0 ? (
          orders.map((order) => (
            <button
              key={order.id}
              onClick={() => navigate({ to: `/pedido/${order.id}` })}
              className="w-full flex items-center gap-4 bg-zinc-950 border border-zinc-900 p-4 rounded-2xl active:scale-[0.98] transition-transform text-left"
            >
              <img
                src={
                  order.merchants?.logo_url ||
                  "https://images.unsplash.com/photo-1546069901-ba9599a7e63c"
                }
                className="w-12 h-12 rounded-xl object-cover ring-1 ring-white/10"
                alt=""
              />
              <div className="flex-1">
                <div className="flex justify-between items-start">
                  <h3 className="font-bold text-white leading-tight">
                    {order.merchants?.name || "Estabelecimento"}
                  </h3>
                  <span className="text-[10px] font-black uppercase text-primary bg-primary/10 px-2 py-0.5 rounded-full ring-1 ring-primary/20">
                    {order.status}
                  </span>
                </div>
                <p className="text-[11px] text-zinc-500 mt-0.5">
                  Pedido #{order.order_number} •{" "}
                  {new Date(order.created_at).toLocaleDateString("pt-BR")}
                </p>
                <p className="text-sm font-bold text-white mt-1">
                  R$ {Number(order.total).toFixed(2).replace(".", ",")}
                </p>
              </div>
            </button>
          ))
        ) : (
          <div className="h-full flex flex-col items-center justify-center text-center py-20">
            <div className="w-20 h-20 bg-zinc-900 rounded-full flex items-center justify-center mb-4">
              <ShoppingBag className="w-8 h-8 text-zinc-600" />
            </div>
            <h2 className="text-lg font-bold">Nenhum pedido recente</h2>
            <p className="text-zinc-500 text-sm mt-2">Você ainda não realizou pedidos conosco.</p>
          </div>
        )}
      </main>
      <AppBottomNav activeTab="pedidos" />
    </div>
  );
}

import { createFileRoute, useNavigate } from "@tanstack/react-router";
import {
  ArrowLeft,
  ShoppingBag,
  User,
  ChevronRight,
  MapPin,
  CreditCard,
  ClipboardList,
  Heart,
  Bell,
  HelpCircle,
  FileText,
  Star,
  LogOut,
  Store,
  Bike,
  ShieldCheck,
} from "lucide-react";
import { useCart } from "@/contexts/CartContext";
import { useCallback, useEffect, useMemo, useState } from "react";
import { supabase } from "@/integrations/supabase/client";
import { AppBottomNav } from "@/components/AppBottomNav";
import { toast } from "sonner";

export const Route = createFileRoute("/perfil/")({ component: PerfilIndexPage });

function PerfilIndexPage() {
  const navigate = useNavigate();
  const { totalItems } = useCart();
  const [user, setUser] = useState<any>(null);
  const [profile, setProfile] = useState<any>(null);
  const [roles, setRoles] = useState<string[]>([]);
  const [loading, setLoading] = useState(true);

  const getProfile = useCallback(async () => {
    try {
      const {
        data: { user: authUser },
        error: authError,
      } = await supabase.auth.getUser();
      if (authError) throw authError;
      setUser(authUser);
      if (authUser) {
        const [profileResult, rolesResult] = await Promise.all([
          supabase.from("profiles").select("*").eq("id", authUser.id).single(),
          supabase.from("user_roles").select("role").eq("user_id", authUser.id),
        ]);
        if (profileResult.error) throw profileResult.error;
        setProfile(profileResult.data);
        setRoles((rolesResult.data ?? []).map((row: any) => String(row.role)));
      }
    } catch {
      toast.error("Não foi possível atualizar os dados da sua conta.");
    } finally {
      setLoading(false);
    }
  }, []);

  useEffect(() => {
    void getProfile();
    window.addEventListener("focus", getProfile);
    return () => window.removeEventListener("focus", getProfile);
  }, [getProfile]);

  const handleLogout = async () => {
    const { error } = await supabase.auth.signOut();
    if (error) toast.error("Erro ao sair da conta");
    else navigate({ to: "/login" });
  };

  const menuItems = useMemo<any[]>(() => {
    const base: any[] = [
      { icon: User, label: "Dados pessoais", path: "/perfil/dados-pessoais" },
      { icon: MapPin, label: "Meus endereços", path: "/enderecos" },
      { icon: CreditCard, label: "Formas de pagamento", path: "/perfil/pagamentos" },
      { icon: ClipboardList, label: "Meus pedidos", path: "/pedidos" },
      { icon: Heart, label: "Favoritos", path: "/favoritos" },
      { icon: Bell, label: "Notificações", path: "/perfil/notificacoes" },
      { icon: HelpCircle, label: "Ajuda e suporte", path: "/perfil/ajuda" },
      { icon: FileText, label: "Termos de Uso e Privacidade", path: "/perfil/legal" },
      { icon: Star, label: "APOIS+", path: "/apois-plus", highlight: true },
    ];
    const work: any[] = [
      {
        icon: Store,
        label: roles.includes("merchant") ? "Painel do estabelecimento" : "Quero vender na APOIS",
        path: "/merchant",
        work: true,
      },
      {
        icon: Bike,
        label: roles.includes("courier") ? "App do entregador" : "Quero fazer entregas",
        path: "/courier",
        work: true,
      },
    ];
    if (roles.includes("admin"))
      work.push({ icon: ShieldCheck, label: "Administração APOIS", path: "/admin", work: true });
    return [...work, ...base];
  }, [roles]);

  return (
    <div className="relative flex h-screen w-full flex-col overflow-hidden bg-black text-white">
      <header className="z-50 flex shrink-0 items-center justify-between border-b border-zinc-900 bg-black/80 p-4 backdrop-blur-lg">
        <button
          type="button"
          onClick={() => navigate({ to: "/inicio" })}
          className="rounded-full bg-zinc-900 p-2 shadow-lg"
        >
          <ArrowLeft className="h-5 w-5 text-zinc-300" />
        </button>
        <h1 className="text-xl font-bold text-primary">Conta</h1>
        <button
          type="button"
          onClick={() => navigate({ to: "/sacola" })}
          className="relative rounded-full bg-zinc-900 p-2 shadow-lg"
        >
          <ShoppingBag className="h-5 w-5 text-zinc-300" />
          {totalItems > 0 ? (
            <span className="absolute -right-1 -top-1 flex h-4 w-4 items-center justify-center rounded-full border-2 border-black bg-primary text-[10px] font-bold text-black">
              {totalItems}
            </span>
          ) : null}
        </button>
      </header>

      <main className="scrollbar-none flex-1 overflow-y-auto p-4 pb-20">
        <div className="mb-8 flex flex-col items-center rounded-3xl border border-zinc-900/50 bg-zinc-900/40 p-6 backdrop-blur-sm">
          <div className="mb-4 flex h-20 w-20 items-center justify-center rounded-full border-2 border-primary bg-zinc-900 shadow-[0_0_15px_rgba(255,215,0,0.3)]">
            <User className="h-10 w-10 text-primary" />
          </div>
          <h2 className="mb-1 text-xl font-bold">
            {loading ? "Carregando..." : profile?.full_name || "Usuário"}
          </h2>
          <p className="mb-1 text-sm text-zinc-500">{user?.email}</p>
          {profile?.phone ? <p className="text-xs text-zinc-500">{profile.phone}</p> : null}
          <div className="mt-3 flex flex-wrap justify-center gap-2">
            <span className="rounded-full border border-primary/20 bg-primary/10 px-3 py-1 text-[10px] font-black uppercase tracking-widest text-primary">
              Cliente Apois
            </span>
            {roles
              .filter((role) => role !== "customer")
              .map((role) => (
                <span
                  key={role}
                  className="rounded-full border border-zinc-800 bg-zinc-900 px-3 py-1 text-[10px] font-black uppercase tracking-widest text-zinc-400"
                >
                  {role}
                </span>
              ))}
          </div>
        </div>

        <div className="space-y-2">
          {menuItems.map((item) => (
            <button
              key={item.path}
              type="button"
              onClick={() => window.location.assign(item.path)}
              className={`flex w-full items-center justify-between rounded-2xl border p-4 transition-all active:scale-[0.98] ${item.highlight ? "border-primary/20 bg-primary/5 text-primary" : item.work ? "border-primary/10 bg-zinc-950 text-white hover:border-primary/30" : "border-zinc-900/50 bg-zinc-900/40 text-zinc-300 hover:bg-zinc-900/60"}`}
            >
              <div className="flex items-center gap-4">
                <div
                  className={`rounded-xl p-2.5 ${item.highlight || item.work ? "bg-primary/10 text-primary" : "bg-zinc-800"}`}
                >
                  <item.icon className="h-5 w-5" />
                </div>
                <span className="text-sm font-medium">{item.label}</span>
              </div>
              <ChevronRight
                className={`h-4 w-4 ${item.highlight || item.work ? "text-primary/50" : "text-zinc-600"}`}
              />
            </button>
          ))}

          <button
            type="button"
            onClick={handleLogout}
            className="mt-6 flex w-full items-center justify-between rounded-2xl border border-red-500/10 bg-red-500/5 p-4 text-red-400 transition-all active:scale-[0.98] hover:bg-red-500/10"
          >
            <div className="flex items-center gap-4">
              <div className="rounded-xl bg-red-500/10 p-2.5">
                <LogOut className="h-5 w-5" />
              </div>
              <span className="text-sm font-medium">Sair da conta</span>
            </div>
            <ChevronRight className="h-4 w-4 opacity-30" />
          </button>
        </div>
      </main>
      <AppBottomNav activeTab="perfil" />
    </div>
  );
}

import { createFileRoute, Link, useNavigate, redirect } from "@tanstack/react-router";
import { Button } from "@/components/ui/button";
import { Input } from "@/components/ui/input";
import { Checkbox } from "@/components/ui/checkbox";
import { ChevronLeft, Eye, EyeOff, Loader2 } from "lucide-react";
import { useState, useMemo } from "react";
import logoAsset from "@/assets/logo.png.asset.json";
import { toast } from "sonner";
import { supabase } from "@/integrations/supabase/client";

export const Route = createFileRoute("/register")({
  beforeLoad: async () => {
    const {
      data: { session },
    } = await supabase.auth.getSession();
    if (session) {
      throw redirect({ to: "/inicio" });
    }
  },
  component: Register,
  head: () => ({
    title: "Criar conta - APOIS ENTREGA",
    meta: [{ name: "description", content: "Crie sua conta no APOIS ENTREGA" }],
  }),
});

function Register() {
  const navigate = useNavigate();
  const [showPassword, setShowPassword] = useState(false);
  const [isLoading, setIsLoading] = useState(false);
  const [formData, setFormData] = useState({
    fullName: "",
    phone: "",
    email: "",
    password: "",
    confirmPassword: "",
    acceptTerms: false,
  });

  const [submitted, setSubmitted] = useState(false);
  const [touched, setTouched] = useState({
    fullName: false,
    phone: false,
    email: false,
    password: false,
    confirmPassword: false,
  });

  // Brazilian Phone Mask: (00) 00000-0000
  const maskPhone = (value: string) => {
    const numbers = value.replace(/\D/g, "");
    if (numbers.length <= 2) return numbers;
    if (numbers.length <= 7) return `(${numbers.slice(0, 2)}) ${numbers.slice(2)}`;
    return `(${numbers.slice(0, 2)}) ${numbers.slice(2, 7)}-${numbers.slice(7, 11)}`;
  };

  const handlePhoneChange = (e: React.ChangeEvent<HTMLInputElement>) => {
    const maskedValue = maskPhone(e.target.value);
    setFormData({ ...formData, phone: maskedValue });
  };

  // Validations
  const errors = useMemo(() => {
    const newErrors: Record<string, string> = {};

    if (!formData.fullName.trim()) {
      newErrors["fullName"] = "Campo obrigatório";
    } else if (formData.fullName.trim().split(" ").length < 2) {
      newErrors["fullName"] = "Digite seu nome completo (nome e sobrenome)";
    }

    if (!formData.phone.replace(/\D/g, "")) {
      newErrors["phone"] = "Campo obrigatório";
    } else if (formData.phone.replace(/\D/g, "").length < 10) {
      newErrors["phone"] = "Telefone incompleto";
    }

    const emailRegex = /^[^\s@]+@[^\s@]+\.[^\s@]+$/;
    if (!formData.email) {
      newErrors["email"] = "Campo obrigatório";
    } else if (!emailRegex.test(formData.email)) {
      newErrors["email"] = "E-mail inválido";
    }

    if (!formData.password) {
      newErrors["password"] = "Campo obrigatório";
    } else if (formData.password.length < 8) {
      newErrors["password"] = "A senha deve ter no mínimo 8 caracteres";
    }

    if (!formData.confirmPassword) {
      newErrors["confirmPassword"] = "Campo obrigatório";
    } else if (formData.confirmPassword !== formData.password) {
      newErrors["confirmPassword"] = "As senhas não coincidem";
    }

    return newErrors;
  }, [formData]);

  const missingFields = useMemo(() => {
    const missing: string[] = [];
    if (formData.fullName.trim().split(" ").length < 2) missing.push("Nome completo");
    if (formData.phone.replace(/\D/g, "").length < 10) missing.push("Telefone");
    const emailRegex = /^[^\s@]+@[^\s@]+\.[^\s@]+$/;
    if (!emailRegex.test(formData.email)) missing.push("E-mail válido");
    if (formData.password.length < 8) missing.push("Senha (mín. 8 chars)");
    if (formData.password !== formData.confirmPassword) missing.push("Confirmação de senha");
    if (!formData.acceptTerms) missing.push("Aceite dos termos");
    return missing;
  }, [formData]);

  const isFormValid = missingFields.length === 0;

  const handleSubmit = async (e: React.FormEvent) => {
    e.preventDefault();
    setSubmitted(true);
    if (!isFormValid) {
      setTouched({
        fullName: true,
        phone: true,
        email: true,
        password: true,
        confirmPassword: true,
      });
      return;
    }

    if (isLoading) return;

    setIsLoading(true);

    try {
      const redirectTo = `${window.location.origin}/auth/callback`;

      const { data, error } = await supabase.auth.signUp({
        email: formData.email,
        password: formData.password,
        options: {
          emailRedirectTo: redirectTo,
          data: {
            full_name: formData.fullName,
            phone: formData.phone,
          },
        },
      });

      if (error) {
        if (error.message.includes("User already registered")) {
          toast.error("Este e-mail já está cadastrado.");
        } else {
          toast.error(`Erro ao criar conta: ${error.message}`);
        }
        return;
      }

      if (data.session) {
        toast.success("Conta criada e autenticada com sucesso!");
        navigate({ to: "/inicio" });
      } else if (data.user) {
        toast.error(
          "Sua conta foi criada, mas não foi possível iniciar a sessão automaticamente. Por favor, tente fazer login.",
        );
        navigate({ to: "/login" });
      }
    } catch (err: any) {
      toast.error("Ocorreu um erro inesperado ao realizar seu cadastro.");
    } finally {
      setIsLoading(false);
    }
  };

  const showErr = (field: keyof typeof touched) => (touched[field] || submitted) && errors[field];

  return (
    <div className="flex h-full min-h-0 flex-col bg-black text-white overflow-hidden w-full">
      {/* Header with Back Button */}
      <header className="flex items-center px-4 py-2 shrink-0 bg-black">
        <button
          onClick={() => navigate({ to: "/" })}
          className="p-2 -ml-2 hover:bg-white/10 rounded-full transition-colors"
          aria-label="Voltar"
        >
          <ChevronLeft className="w-5 h-5 text-white" />
        </button>
      </header>

      <main className="flex-1 min-h-0 overflow-y-auto px-6 pb-6">
        {/* Logo and Title */}
        <div className="flex flex-col items-center mb-4 text-center">
          <img
            src={logoAsset.url}
            alt="APOIS ENTREGA"
            className="h-12 w-auto object-contain mb-2"
          />
          <h1 className="text-[20px] font-black text-white leading-tight">Crie sua conta</h1>
        </div>

        {/* Google */}
        <Button
          type="button"
          variant="outline"
          className="w-full bg-transparent border-zinc-800 text-white hover:bg-white/5 font-bold h-11 text-sm rounded-xl flex items-center justify-center gap-3 transition-transform active:scale-[0.98] shrink-0"
        >
          <svg viewBox="0 0 24 24" className="w-5 h-5" xmlns="http://www.w3.org/2000/svg">
            <path
              d="M22.56 12.25c0-.78-.07-1.53-.2-2.25H12v4.26h5.92c-.26 1.37-1.04 2.53-2.21 3.31v2.77h3.57c2.08-1.92 3.28-4.74 3.28-8.09z"
              fill="#4285F4"
            />
            <path
              d="M12 23c2.97 0 5.46-.98 7.28-2.66l-3.57-2.77c-.98.66-2.23 1.06-3.71 1.06-2.86 0-5.29-1.93-6.16-4.53H2.18v2.84C3.99 20.53 7.7 23 12 23z"
              fill="#34A853"
            />
            <path
              d="M5.84 14.09c-.22-.66-.35-1.36-.35-2.09s.13-1.43.35-2.09V7.07H2.18C1.43 8.55 1 10.22 1 12s.43 3.45 1.18 4.93l3.66-2.84z"
              fill="#FBBC05"
            />
            <path
              d="M12 5.38c1.62 0 3.06.56 4.21 1.66l3.15-3.15C17.45 2.09 14.97 1 12 1 7.7 1 3.99 3.47 2.18 7.07l3.66 2.84c.87-2.6 3.3-4.53 6.16-4.53z"
              fill="#EA4335"
            />
          </svg>
          <span>Continuar com Google</span>
        </Button>

        <div className="flex items-center gap-4 py-3">
          <div className="h-px flex-1 bg-zinc-800" />
          <span className="text-zinc-500 text-[10px] font-medium uppercase tracking-wider">ou</span>
          <div className="h-px flex-1 bg-zinc-800" />
        </div>

        {/* Register Form */}
        <form onSubmit={handleSubmit} className="space-y-3" noValidate>
          <div className="space-y-1">
            <label className="text-[11px] font-medium text-zinc-400 ml-1">Nome completo</label>
            <Input
              type="text"
              placeholder="Digite seu nome completo"
              value={formData.fullName}
              onChange={(e) => setFormData({ ...formData, fullName: e.target.value })}
              onBlur={() => setTouched({ ...touched, fullName: true })}
              className={`bg-zinc-900/50 border-zinc-800 h-11 rounded-xl text-white text-sm placeholder:text-zinc-600 focus:ring-primary focus:border-primary ${showErr("fullName") ? "border-red-500/50" : ""}`}
            />
            {showErr("fullName") && (
              <p className="text-[10px] text-red-500 ml-1">{errors["fullName"]}</p>
            )}
          </div>

          <div className="space-y-1">
            <label className="text-[11px] font-medium text-zinc-400 ml-1">Telefone celular</label>
            <Input
              type="tel"
              placeholder="(00) 00000-0000"
              value={formData.phone}
              onChange={handlePhoneChange}
              onBlur={() => setTouched({ ...touched, phone: true })}
              className={`bg-zinc-900/50 border-zinc-800 h-11 rounded-xl text-white text-sm placeholder:text-zinc-600 focus:ring-primary focus:border-primary ${showErr("phone") ? "border-red-500/50" : ""}`}
            />
            {showErr("phone") && <p className="text-[10px] text-red-500 ml-1">{errors["phone"]}</p>}
          </div>

          <div className="space-y-1">
            <label className="text-[11px] font-medium text-zinc-400 ml-1">E-mail</label>
            <Input
              type="email"
              placeholder="seu@email.com"
              value={formData.email}
              onChange={(e) => setFormData({ ...formData, email: e.target.value })}
